/* https://www.nesdev.org/wiki/INES_Mapper_052
 * Mapper 52 — 7-in-1 multicart (MMC3 + outer bank via SRAM).
 * SRAM write at $6000-$7FFF:
 *   bits[2:0]: outer PRG bank (selects 128KB PRG segment)
 *   bits[5:3]: outer CHR bank (selects 64KB CHR segment)
 *   bit[6]:    mode: 0=normal, 1=lock outer register
 * All inner MMC3 behaviour applies within the selected segment.
 */

typedef struct {
    uint8_t bank_select;
    uint8_t bank_values[8];
    uint8_t mirroring;
    uint8_t irq_latch;
    uint8_t irq_counter;
    uint8_t irq_reload;
    uint8_t irq_enabled;
    uint8_t prg_bank_count;
    uint8_t chr_bank_count;
    uint8_t outer;
    uint8_t locked;
} mapper52_t;

static void nes_mapper_deinit(nes_t* nes) {
    nes_free(nes->nes_mapper.mapper_register);
    nes->nes_mapper.mapper_register = NULL;
}

static void mapper52_update_banks(nes_t* nes) {
    mapper52_t* m = (mapper52_t*)nes->nes_mapper.mapper_register;
    uint8_t prg_mode = (m->bank_select >> 6) & 1u;
    uint8_t chr_mode = (m->bank_select >> 7) & 1u;
    uint8_t outer_prg = m->outer & 0x07u;
    uint8_t outer_chr = (m->outer >> 3) & 0x07u;
    uint8_t prg_off = (uint8_t)(outer_prg * 16u);  /* 128KB / 8KB = 16 banks */
    uint8_t chr_off = (uint8_t)(outer_chr * 8u);   /* 64KB  / 8KB = 8 banks — 1KB units: *8 */

    if (prg_off >= m->prg_bank_count) prg_off = 0u;
    if (chr_off >= m->chr_bank_count) chr_off = 0u;

    uint8_t last  = (uint8_t)(prg_off + 15u);
    uint8_t slast = (uint8_t)(prg_off + 14u);
    if (last  >= m->prg_bank_count) last  = (uint8_t)(m->prg_bank_count - 1u);
    if (slast >= m->prg_bank_count) slast = (uint8_t)(m->prg_bank_count - 2u);

    if (prg_mode == 0u) {
        nes_load_prgrom_8k(nes, 0, (uint8_t)(prg_off + m->bank_values[6] % 16u));
        nes_load_prgrom_8k(nes, 1, (uint8_t)(prg_off + m->bank_values[7] % 16u));
        nes_load_prgrom_8k(nes, 2, slast);
        nes_load_prgrom_8k(nes, 3, last);
    } else {
        nes_load_prgrom_8k(nes, 0, slast);
        nes_load_prgrom_8k(nes, 1, (uint8_t)(prg_off + m->bank_values[7] % 16u));
        nes_load_prgrom_8k(nes, 2, (uint8_t)(prg_off + m->bank_values[6] % 16u));
        nes_load_prgrom_8k(nes, 3, last);
    }

    if (m->chr_bank_count == 0u) return;
    uint8_t cs = 8u;  /* CHR segment size (64KB = 64 × 1KB banks) */
    /* chr_off is in 8 1KB units, so the segment is chr_off to chr_off+63 */
    /* For simplicity: chr_off in 8-bank steps, actual seg is 64 banks */
    chr_off = (uint8_t)(outer_chr * 64u);  /* 64KB per step = 64 1KB banks */
    if (chr_off >= m->chr_bank_count) chr_off = 0u;
    cs = 64u;

    if (chr_mode == 0u) {
        nes_load_chrrom_1k(nes, 0, (uint8_t)(chr_off + (m->bank_values[0] & 0xFEu) % cs));
        nes_load_chrrom_1k(nes, 1, (uint8_t)(chr_off + (m->bank_values[0] | 0x01u) % cs));
        nes_load_chrrom_1k(nes, 2, (uint8_t)(chr_off + (m->bank_values[1] & 0xFEu) % cs));
        nes_load_chrrom_1k(nes, 3, (uint8_t)(chr_off + (m->bank_values[1] | 0x01u) % cs));
        nes_load_chrrom_1k(nes, 4, (uint8_t)(chr_off + m->bank_values[2] % cs));
        nes_load_chrrom_1k(nes, 5, (uint8_t)(chr_off + m->bank_values[3] % cs));
        nes_load_chrrom_1k(nes, 6, (uint8_t)(chr_off + m->bank_values[4] % cs));
        nes_load_chrrom_1k(nes, 7, (uint8_t)(chr_off + m->bank_values[5] % cs));
    } else {
        nes_load_chrrom_1k(nes, 0, (uint8_t)(chr_off + m->bank_values[2] % cs));
        nes_load_chrrom_1k(nes, 1, (uint8_t)(chr_off + m->bank_values[3] % cs));
        nes_load_chrrom_1k(nes, 2, (uint8_t)(chr_off + m->bank_values[4] % cs));
        nes_load_chrrom_1k(nes, 3, (uint8_t)(chr_off + m->bank_values[5] % cs));
        nes_load_chrrom_1k(nes, 4, (uint8_t)(chr_off + (m->bank_values[0] & 0xFEu) % cs));
        nes_load_chrrom_1k(nes, 5, (uint8_t)(chr_off + (m->bank_values[0] | 0x01u) % cs));
        nes_load_chrrom_1k(nes, 6, (uint8_t)(chr_off + (m->bank_values[1] & 0xFEu) % cs));
        nes_load_chrrom_1k(nes, 7, (uint8_t)(chr_off + (m->bank_values[1] | 0x01u) % cs));
    }
}

static void nes_mapper_init(nes_t* nes) {
    if (nes->nes_mapper.mapper_register == NULL) {
        nes->nes_mapper.mapper_register = nes_malloc(sizeof(mapper52_t));
        if (nes->nes_mapper.mapper_register == NULL) return;
    }
    mapper52_t* m = (mapper52_t*)nes->nes_mapper.mapper_register;
    nes_memset(m, 0, sizeof(mapper52_t));

    m->prg_bank_count = (uint8_t)(nes->nes_rom.prg_rom_size * 2u);
    m->chr_bank_count = (uint8_t)(nes->nes_rom.chr_rom_size * 8u);
    m->bank_values[6] = 0;
    m->bank_values[7] = 1;

    if (nes->nes_rom.chr_rom_size == 0u) nes_load_chrrom_8k(nes, 0, 0);
    mapper52_update_banks(nes);
}

static void nes_mapper_write(nes_t* nes, uint16_t address, uint8_t data) {
    mapper52_t* m = (mapper52_t*)nes->nes_mapper.mapper_register;
    switch (address & 0xE001u) {
    case 0x8000: m->bank_select = data; mapper52_update_banks(nes); break;
    case 0x8001: {
        uint8_t reg = m->bank_select & 0x07u;
        m->bank_values[reg] = data;
        mapper52_update_banks(nes);
        break;
    }
    case 0xA000:
        m->mirroring = data & 1u;
        if (nes->nes_rom.four_screen == 0)
            nes_ppu_screen_mirrors(nes, m->mirroring ? NES_MIRROR_HORIZONTAL : NES_MIRROR_VERTICAL);
        break;
    case 0xA001: break;
    case 0xC000: m->irq_latch   = data; break;
    case 0xC001: m->irq_reload  = 1; break;
    case 0xE000: m->irq_enabled = 0; nes->nes_cpu.irq_pending = 0; break;
    case 0xE001: m->irq_enabled = 1; break;
    default: break;
    }
}

static void nes_mapper_sram(nes_t* nes, uint16_t address, uint8_t data) {
    mapper52_t* m = (mapper52_t*)nes->nes_mapper.mapper_register;
    (void)address;
    if (m->locked) return;
    if (data & 0x40u) m->locked = 1u;
    m->outer = data & 0x3Fu;
    mapper52_update_banks(nes);
}

static void nes_mapper_hsync(nes_t* nes) {
    mapper52_t* m = (mapper52_t*)nes->nes_mapper.mapper_register;
    if (nes->nes_ppu.MASK_b == 0 && nes->nes_ppu.MASK_s == 0) return;
    if (m->irq_counter == 0u || m->irq_reload) {
        m->irq_counter = m->irq_latch;
    } else {
        m->irq_counter--;
    }
    if (m->irq_counter == 0u && m->irq_enabled) nes_cpu_irq(nes);
    m->irq_reload = 0;
}

int nes_mapper52_init(nes_t* nes) {
    nes->nes_mapper.mapper_init   = nes_mapper_init;
    nes->nes_mapper.mapper_deinit = nes_mapper_deinit;
    nes->nes_mapper.mapper_write  = nes_mapper_write;
    nes->nes_mapper.mapper_sram   = nes_mapper_sram;
    nes->nes_mapper.mapper_hsync  = nes_mapper_hsync;
    return NES_OK;
}

