/* https://www.nesdev.org/wiki/INES_Mapper_087
 * Jaleco JF-09 / Konami — 32KB PRG-ROM fixed; 8KB CHR-ROM switchable.
 * Write to $6000-$7FFF: bits[1:0] of data are bit-swapped for CHR bank:
 *   bank = ((data & 1) << 1) | ((data >> 1) & 1)
 */

static void nes_mapper_init(nes_t* nes) {
    nes_load_prgrom_32k(nes, 0, 0);
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, 0);
    }
}

static void nes_mapper_sram(nes_t* nes, uint16_t address, uint8_t data) {
    (void)address;
    if (nes->nes_rom.chr_rom_size > 0) {
        uint8_t bank = (uint8_t)(((data & 1u) << 1u) | ((data >> 1u) & 1u));
        nes_load_chrrom_8k(nes, 0, bank);
    }
}

int nes_mapper87_init(nes_t* nes) {
    nes->nes_mapper.mapper_init = nes_mapper_init;
    nes->nes_mapper.mapper_sram = nes_mapper_sram;
    return NES_OK;
}

