/* https://www.nesdev.org/wiki/INES_Mapper_140
 * Jaleco JF-11 / JF-14 — PRG 32KB switchable; CHR 8KB switchable.
 * Write $6000-$7FFF:
 *   bits[3:0] = CHR 8KB bank
 *   bits[7:4] = PRG 32KB bank
 */

static void nes_mapper_init(nes_t* nes) {
    nes_load_prgrom_32k(nes, 0, 0);
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, 0);
    }
}

static void nes_mapper_sram(nes_t* nes, uint16_t address, uint8_t data) {
    (void)address;
    nes_load_prgrom_32k(nes, 0, (uint16_t)((data >> 4) & 0x0Fu));
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, (uint8_t)(data & 0x0Fu));
    }
}

int nes_mapper140_init(nes_t* nes) {
    nes->nes_mapper.mapper_init = nes_mapper_init;
    nes->nes_mapper.mapper_sram = nes_mapper_sram;
    return NES_OK;
}

