/* https://www.nesdev.org/wiki/INES_Mapper_150
 * Mapper 150 — 74LS374N (Sachen).
 * APU $4100: register select via read; SRAM write: register data.
 * Same bank structure as the Sachen 8259 family.
 */

typedef struct {
    uint8_t regs[8];
    uint8_t reg_sel;
    uint8_t prg_bank_count;
    uint8_t chr_bank_count;
} mapper150_t;

static void nes_mapper_deinit(nes_t* nes) {
    nes_free(nes->nes_mapper.mapper_register);
    nes->nes_mapper.mapper_register = NULL;
}

static void mapper150_update_banks(nes_t* nes) {
    mapper150_t* m = (mapper150_t*)nes->nes_mapper.mapper_register;

    if (m->prg_bank_count > 0u) {
        uint8_t prg = m->regs[5] % m->prg_bank_count;
        uint8_t last = (uint8_t)(m->prg_bank_count - 1u);
        nes_load_prgrom_8k(nes, 0, prg);
        nes_load_prgrom_8k(nes, 1, prg);
        nes_load_prgrom_8k(nes, 2, last);
        nes_load_prgrom_8k(nes, 3, last);
    }

    if (m->chr_bank_count > 0u) {
        for (uint8_t i = 0u; i < 4u; i++) {
            uint8_t b = (uint8_t)((m->regs[i] * 2u) % m->chr_bank_count);
            nes_load_chrrom_1k(nes, (uint8_t)(i * 2u),       b);
            nes_load_chrrom_1k(nes, (uint8_t)(i * 2u + 1u), (uint8_t)((b + 1u) % m->chr_bank_count));
        }
    }

    if (nes->nes_rom.four_screen == 0)
        nes_ppu_screen_mirrors(nes, (m->regs[4] & 1u) ? NES_MIRROR_HORIZONTAL : NES_MIRROR_VERTICAL);
}

static void nes_mapper_init(nes_t* nes) {
    if (nes->nes_mapper.mapper_register == NULL) {
        nes->nes_mapper.mapper_register = nes_malloc(sizeof(mapper150_t));
        if (nes->nes_mapper.mapper_register == NULL) return;
    }
    mapper150_t* m = (mapper150_t*)nes->nes_mapper.mapper_register;
    nes_memset(m, 0, sizeof(mapper150_t));
    m->prg_bank_count = (uint8_t)(nes->nes_rom.prg_rom_size * 2u);
    m->chr_bank_count = (uint8_t)(nes->nes_rom.chr_rom_size * 8u);
    mapper150_update_banks(nes);
}

static void nes_mapper_sram(nes_t* nes, uint16_t address, uint8_t data) {
    mapper150_t* m = (mapper150_t*)nes->nes_mapper.mapper_register;
    (void)address;
    m->regs[m->reg_sel] = data;
    mapper150_update_banks(nes);
}

static uint8_t nes_mapper_read_apu(nes_t* nes, uint16_t address) {
    mapper150_t* m = (mapper150_t*)nes->nes_mapper.mapper_register;
    m->reg_sel = address & 0x07u;
    return m->regs[m->reg_sel];
}

int nes_mapper150_init(nes_t* nes) {
    nes->nes_mapper.mapper_init     = nes_mapper_init;
    nes->nes_mapper.mapper_deinit   = nes_mapper_deinit;
    nes->nes_mapper.mapper_sram     = nes_mapper_sram;
    nes->nes_mapper.mapper_read_apu = nes_mapper_read_apu;
    return NES_OK;
}

#undef mapper150_update_banks
#undef nes_mapper_deinit
#undef nes_mapper_init
#undef nes_mapper_read_apu
#undef nes_mapper_sram


