/* https://www.nesdev.org/wiki/INES_Mapper_188
 * Bandai Karaoke Studio — 16KB PRG switchable (XOR'd with 4).
 * Write $8000-$FFFF: bits[3:0] XOR 4 = 16KB PRG bank for $8000-$BFFF.
 * Fixed last 16KB at $C000-$FFFF.
 */

static void nes_mapper_init(nes_t* nes) {
    /* Karaoke Studio ROM starts from bank 4 (XOR with 4 on bank 0 gives 4) */
    nes_load_prgrom_16k(nes, 0, 4);
    nes_load_prgrom_16k(nes, 1, (uint16_t)(nes->nes_rom.prg_rom_size - 1));
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, 0);
    }
}

static void nes_mapper_write(nes_t* nes, uint16_t address, uint8_t data) {
    (void)address;
    nes_load_prgrom_16k(nes, 0, (uint16_t)((data & 0x0Fu) ^ 0x04u));
}

int nes_mapper188_init(nes_t* nes) {
    nes->nes_mapper.mapper_init  = nes_mapper_init;
    nes->nes_mapper.mapper_write = nes_mapper_write;
    return NES_OK;
}

#undef nes_mapper_init
#undef nes_mapper_write


