/* https://www.nesdev.org/wiki/INES_Mapper_200
 * 1200-in-1 multicart — PRG+CHR bank encoded in address bits[2:0].
 * Write $8000-$FFFF: address bits[2:0] = 16KB PRG bank and 8KB CHR bank.
 * Mirroring from address bit[3] (0=V, 1=H).
 */

static void nes_mapper_init(nes_t* nes) {
    nes_load_prgrom_16k(nes, 0, 0);
    nes_load_prgrom_16k(nes, 1, 0);
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, 0);
    }
}

static void nes_mapper_write(nes_t* nes, uint16_t address, uint8_t data) {
    (void)data;
    uint8_t bank = (uint8_t)(address & 0x07u);
    nes_load_prgrom_16k(nes, 0, bank);
    nes_load_prgrom_16k(nes, 1, bank);
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, bank);
    }
    if (nes->nes_rom.four_screen == 0) {
        nes_ppu_screen_mirrors(nes, (address & 0x08u) ? NES_MIRROR_HORIZONTAL : NES_MIRROR_VERTICAL);
    }
}

int nes_mapper200_init(nes_t* nes) {
    nes->nes_mapper.mapper_init  = nes_mapper_init;
    nes->nes_mapper.mapper_write = nes_mapper_write;
    return NES_OK;
}

#undef nes_mapper_init
#undef nes_mapper_write


