/* https://www.nesdev.org/wiki/INES_Mapper_202
 * 150-in-1 multicart — PRG 16KB + CHR 8KB via address bits[2:1].
 * Write $8000-$FFFF: address[2:1] = bank; address[0] = mirror.
 */

static void nes_mapper_init(nes_t* nes) {
    nes_load_prgrom_16k(nes, 0, 0);
    nes_load_prgrom_16k(nes, 1, 1);
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, 0);
    }
}

static void nes_mapper_write(nes_t* nes, uint16_t address, uint8_t data) {
    (void)data;
    uint8_t bank = (uint8_t)((address >> 1) & 0x07u);
    nes_load_prgrom_16k(nes, 0, bank);
    nes_load_prgrom_16k(nes, 1, (uint8_t)(bank + 1u));
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, bank);
    }
    if (nes->nes_rom.four_screen == 0) {
        nes_ppu_screen_mirrors(nes, (address & 0x01u) ? NES_MIRROR_HORIZONTAL : NES_MIRROR_VERTICAL);
    }
}

int nes_mapper202_init(nes_t* nes) {
    nes->nes_mapper.mapper_init  = nes_mapper_init;
    nes->nes_mapper.mapper_write = nes_mapper_write;
    return NES_OK;
}

#undef nes_mapper_init
#undef nes_mapper_write


