/* https://www.nesdev.org/wiki/INES_Mapper_233
 * 42-in-1 reset-based multicart — on reset increments game.
 * Simplified: boot to game 0 (PRG bank 0, 32KB mode, CHR bank 0).
 * Write $8000-$FFFF: bits[4:0]=bank, bit[5]=mode (0=32KB, 1=16KB), bit[6]=CHR.
 */

static void nes_mapper_init(nes_t* nes) {
    nes_load_prgrom_32k(nes, 0, 0);
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, 0);
    }
}

static void nes_mapper_write(nes_t* nes, uint16_t address, uint8_t data) {
    (void)address;
    uint8_t bank = (uint8_t)(data & 0x1Fu);
    if (data & 0x20u) {
        /* 16KB mode */
        nes_load_prgrom_16k(nes, 0, bank);
        nes_load_prgrom_16k(nes, 1, bank);
    } else {
        nes_load_prgrom_32k(nes, 0, (uint16_t)(bank >> 1));
    }
    if (nes->nes_rom.chr_rom_size > 0) {
        nes_load_chrrom_8k(nes, 0, (uint8_t)((data >> 6) & 1u));
    }
}

int nes_mapper233_init(nes_t* nes) {
    nes->nes_mapper.mapper_init  = nes_mapper_init;
    nes->nes_mapper.mapper_write = nes_mapper_write;
    return NES_OK;
}

#undef nes_mapper_init
#undef nes_mapper_write


