/* https://www.nesdev.org/wiki/INES_Mapper_243
 * Mapper 243 — SA-020A (Sachen).
 * Like mapper 79 (NINA-03/06) but with a different register decode.
 * Write to $4100 area: bits[2:0] → CHR bank; bit[3] → PRG bank.
 */

typedef struct {
    uint8_t reg;
    uint8_t prg_bank_count;
    uint8_t chr_bank_count;
} mapper243_t;

static void nes_mapper_deinit(nes_t* nes) {
    nes_free(nes->nes_mapper.mapper_register);
    nes->nes_mapper.mapper_register = NULL;
}

static void mapper243_update_banks(nes_t* nes) {
    mapper243_t* m = (mapper243_t*)nes->nes_mapper.mapper_register;
    uint8_t prg32 = (uint8_t)(m->prg_bank_count / 4u);
    uint8_t chr8  = (uint8_t)(m->chr_bank_count / 8u);
    if (prg32 == 0u) prg32 = 1u;
    if (chr8  == 0u) chr8  = 1u;
    nes_load_prgrom_32k(nes, 0, (uint16_t)(((m->reg >> 3u) & 0x01u) % prg32));
    nes_load_chrrom_8k(nes, 0, (uint8_t)((m->reg & 0x07u) % chr8));
}

static void nes_mapper_init(nes_t* nes) {
    if (nes->nes_mapper.mapper_register == NULL) {
        nes->nes_mapper.mapper_register = nes_malloc(sizeof(mapper243_t));
        if (nes->nes_mapper.mapper_register == NULL) return;
    }
    mapper243_t* m = (mapper243_t*)nes->nes_mapper.mapper_register;
    nes_memset(m, 0, sizeof(mapper243_t));
    m->prg_bank_count = (uint8_t)(nes->nes_rom.prg_rom_size * 2u);
    m->chr_bank_count = (uint8_t)(nes->nes_rom.chr_rom_size * 8u);
    mapper243_update_banks(nes);
}

static void nes_mapper_apu(nes_t* nes, uint16_t address, uint8_t data) {
    mapper243_t* m = (mapper243_t*)nes->nes_mapper.mapper_register;
    (void)address;
    m->reg = data;
    mapper243_update_banks(nes);
}

int nes_mapper243_init(nes_t* nes) {
    nes->nes_mapper.mapper_init   = nes_mapper_init;
    nes->nes_mapper.mapper_deinit = nes_mapper_deinit;
    nes->nes_mapper.mapper_apu    = nes_mapper_apu;
    return NES_OK;
}

#undef mapper243_update_banks
#undef nes_mapper_apu
#undef nes_mapper_deinit
#undef nes_mapper_init


